import { Request, Response, Router } from "express";
import { DomainError } from "../domain/errors";
import { OrderState } from "../domain/order";
import { OrderService } from "../application/order-service";

const STATES: readonly OrderState[] = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"];

export class OrderController {
  public constructor(private readonly service: OrderService) {}

  public router(): Router {
    const router = Router();
    router.post("/products", this.handle((req) => this.service.addProduct(req.body.id, req.body.name, req.body.stock)));
    router.get("/products", this.handle(() => this.service.listProducts()));
    router.post("/orders", this.handle((req) => this.service.placeOrder({ customerId: req.body.customerId, items: req.body.items })));
    router.get("/orders", this.handle((req) => this.service.listOrders(this.stateFrom(req.query.state))));
    router.patch("/orders/:id/state", this.handle((req) => this.service.changeState(this.requiredText(req.params.id, "order id"), this.requiredState(req.body.state))));
    router.post("/orders/:id/cancel", this.handle((req) => this.service.cancelOrder(this.requiredText(req.params.id, "order id"))));
    for (const state of ["paid", "packed", "shipped", "delivered"] as const) {
      router.post(`/orders/:id/${state}`, this.handle((req) => this.service.changeState(this.requiredText(req.params.id, "order id"), state)));
    }
    return router;
  }

  private handle(operation: (request: Request) => unknown): (request: Request, response: Response) => void {
    return (request, response) => {
      try {
        response.status(200).json(operation(request));
      } catch (error) {
        const message = error instanceof Error ? error.message : "Unexpected error";
        response.status(error instanceof DomainError ? 400 : 500).json({ error: message });
      }
    };
  }

  private stateFrom(value: unknown): OrderState | undefined {
    if (value === undefined) return undefined;
    return this.requiredState(value);
  }

  private requiredState(value: unknown): OrderState {
    if (typeof value !== "string" || !STATES.includes(value as OrderState)) {
      throw new DomainError("A valid order state is required");
    }
    return value as OrderState;
  }

  private requiredText(value: string | string[] | undefined, label: string): string {
    if (typeof value !== "string" || value.length === 0) throw new DomainError(`A valid ${label} is required`);
    return value;
  }
}

